/**
 * Isolated Playwright config for the authors-only trial page.
 *
 * It deliberately does NOT reuse `playwright.config.ts`: that config targets the
 * production deployment (`https://app.fivucsas.com`) and its projects are for
 * the deployed dashboard. This one runs only `e2e/author-trial/`, against a
 * local Vite dev server whose `/api` proxy points at the in-repo stub backend,
 * with Chromium's fake camera (no real camera, no internet):
 *
 *   npx playwright test --config=playwright.author-trial.config.ts
 *
 * The fake Y4M is generated by global-setup.mjs (see fake-camera.mjs).
 */
import path from 'node:path'
import { defineConfig, devices } from '@playwright/test'

const ROOT = process.cwd()
const FAKE_CAMERA = path.join(ROOT, 'e2e', 'author-trial', '.artifacts', 'fake-camera.y4m')
const STUB_PORT = 4321
const WEB_PORT = 4322

export default defineConfig({
    testDir: './e2e/author-trial',
    testMatch: /author-trial\.spec\.ts/,
    fullyParallel: false,
    forbidOnly: !!process.env.CI,
    retries: 0,
    workers: 1,
    reporter: 'list',
    timeout: 120_000,
    expect: { timeout: 20_000 },
    globalSetup: './e2e/author-trial/global-setup.mjs',
    use: {
        baseURL: `http://127.0.0.1:${WEB_PORT}`,
        locale: 'en-US',
        trace: 'retain-on-failure',
        screenshot: 'only-on-failure',
        actionTimeout: 20_000,
        navigationTimeout: 60_000,
    },
    webServer: [
        {
            command: 'node e2e/author-trial/stub-server.mjs',
            url: `http://127.0.0.1:${STUB_PORT}/health`,
            reuseExistingServer: false,
            timeout: 30_000,
            env: { AUTHOR_TRIAL_STUB_PORT: String(STUB_PORT) },
        },
        {
            // Same-origin API: the page calls http://127.0.0.1:4312/api/v1 and
            // Vite proxies /api to the stub, so no CORS and no CSP exception.
            command: `node node_modules/vite/bin/vite.js --host 127.0.0.1 --port ${WEB_PORT} --strictPort`,
            url: `http://127.0.0.1:${WEB_PORT}`,
            reuseExistingServer: false,
            timeout: 120_000,
            env: {
                VITE_API_BASE_URL: `http://127.0.0.1:${WEB_PORT}/api/v1`,
                VITE_DEV_API_PROXY: `http://127.0.0.1:${STUB_PORT}`,
                VITE_CLIENT_SIDE_EMBEDDING: 'true',
                VITE_APP_VERSION: 'e2e-local',
                VITE_ENVIRONMENT: 'test',
            },
        },
    ],
    projects: [
        {
            name: 'author-trial',
            use: {
                ...devices['Desktop Chrome'],
                // A real installed Chrome (fake camera flags still apply). Set
                // AUTHOR_TRIAL_BROWSER_CHANNEL='' to use a downloaded Chromium.
                channel: process.env.AUTHOR_TRIAL_BROWSER_CHANNEL ?? 'chrome',
                launchOptions: {
                    args: [
                        '--use-fake-ui-for-media-stream',
                        '--use-fake-device-for-media-stream',
                        `--use-file-for-fake-video-capture=${FAKE_CAMERA}`,
                    ],
                },
            },
        },
    ],
})